-- 0020 · TỔ CHỨC: phòng ban · chức năng nhiệm vụ · quy trình A–Z · đầu vào/đầu ra giữa phòng ban · chủ đề event bus (dữ liệu chạy thẳng, không phải đi hỏi)
create table if not exists departments(code text primary key, org_id text default 'ITRAN', name text not null, short text, parent_code text, level int default 1, block text, -- DIEU_HANH|SAN_XUAT|CHUOI_CUNG_UNG|KINH_DOANH|HO_TRO|CHIEN_LUOC
  mission text, functions text[] default '{}', head_role text, roles text[] default '{}', kpis text[] default '{}', records text[] default '{}', dashboards text[] default '{}', modules text[] default '{}', per_farm bool default true, position int default 0, active bool default true);
create table if not exists processes(code text primary key, dept_code text references departments, name text not null, kind text, -- CORE|SUPPORT|MANAGEMENT
  trigger_text text, inputs jsonb default '[]'::jsonb, -- [{from:dept, what, table/topic}]
  outputs jsonb default '[]'::jsonb, -- [{to:dept, what, table/topic}]
  sla text, owner_role text, kpi text, tables text[] default '{}', topics text[] default '{}', forms text[] default '{}', sop_code text, position int default 0, active bool default true);
create table if not exists process_steps(id serial primary key, process_code text references processes, step_no int not null, name text not null, actor_role text, dept_code text, action text, -- mô tả làm gì
  system_where text, -- màn hình/API/bảng
  raci jsonb default '{}'::jsonb, control text, output text, unique(process_code, step_no));
create table if not exists dept_links(id serial primary key, from_dept text references departments, to_dept text references departments, what text not null, via text, -- table/topic/view/export
  frequency text, realtime bool default true, unique(from_dept, to_dept, what));
create table if not exists event_topics(topic text primary key, producer_dept text, consumer_depts text[] default '{}', description text, payload jsonb default '{}'::jsonb, source_table text, wired bool default true);
do $$ declare t text; begin foreach t in array array['departments','processes','process_steps','dept_links','event_topics'] loop
  execute format('alter table %I enable row level security', t); execute format('drop policy if exists p_all on %I', t); execute format('create policy p_all on %I for all using (true) with check (app_role() in (''owner'',''director'',''it_engineer''))', t); execute format('grant select, insert, update on %I to app_user', t); end loop;
  grant usage, select on all sequences in schema public to app_user; end $$;
do $$ declare t text; begin foreach t in array array['departments','processes','process_steps','dept_links','event_topics'] loop
  execute format('drop trigger if exists audit_%1$s on %1$s; create trigger audit_%1$s after insert or update or delete on %1$s for each row execute function itran_audit()', t); end loop; end $$;

