-- Ma trận liên hệ đầu vào/đầu ra (sinh từ processes.inputs/outputs) — view để vẽ
create or replace view v_dept_io as
select p.dept_code as to_dept, i->>'from' as from_dept, i->>'what' as what, i->>'via' as via, p.code as process_code, 'IN' as dir from processes p, jsonb_array_elements(p.inputs) i
union all
select o->>'to' as to_dept, p.dept_code as from_dept, o->>'what' as what, o->>'via' as via, p.code, 'OUT' from processes p, jsonb_array_elements(p.outputs) o;
grant select on v_dept_io to app_user;

