('master.changed','*','{HDQT,CNTB}','Thêm/sửa/gỡ danh mục (audit) → admin','audit_log',true),
('import.done','*','{HDQT,CNTB,BGD}','Nhập CSV xong (ok/lỗi)','import_batches',true),
('animal.intake','KTCN','{CCU,TCKT,KDM}','Lô nhập đàn mới → sổ đàn K8, giá trị đàn, cá thể sẵn sàng nhận nuôi','intake_lots',false),
('harvest.done','TT','{CCU,D5,KDM,QA}','Thu hoạch xong → nhập kho, kế hoạch chế biến/bán, hồ sơ','harvests',false),
('po.created','CCU','{TCKT,GDT}','PO mới → duyệt/công nợ','purchase_orders',false),
('order.created','KDM','{CCU,D5,TCKT}','Đơn bán mới → chuẩn bị hàng, sản xuất, công nợ','orders',false),
('booking.created','DL','{CCU,D5,HCNS}','Booking/tiệc mới → chuẩn bị F&B, nhân sự','hosp_bookings',false),
('shipment.status','XNK','{CCU,TCKT,KDM}','Lô hàng XNK đổi trạng thái','shipments',false),
('lot.blocked','QA','{KDM,CCU,D5}','Lô bị khóa (thu hồi/không phù hợp) → chặn bán/xuất','lots',false),
('period.locked','TCKT','{*}','Khóa kỳ kế toán → chặn ghi lùi','period_locks',false)
on conflict (topic) do update set consumer_depts=excluded.consumer_depts, description=excluded.description, wired=excluded.wired;
-- Nối thêm trigger publish cho các topic đã liệt kê (dữ liệu chạy thẳng giữa phòng ban)
create or replace function itran_generic_publish() returns trigger language plpgsql as $$
declare tp text := TG_ARGV[0]; pk text; begin
  pk := coalesce(to_jsonb(new)->>'id', to_jsonb(new)->>'code');
  perform publish_event(to_jsonb(new)->>'farm_id', tp, jsonb_build_object('table', TG_TABLE_NAME, 'id', pk, 'status', to_jsonb(new)->>'status', 'by', nullif(current_setting('app.staff_id', true),'')));
  return new; end $$;
do $$ begin
  if to_regclass('intake_lots') is not null then execute 'drop trigger if exists pub_intake on intake_lots; create trigger pub_intake after insert on intake_lots for each row execute function itran_generic_publish(''animal.intake'')'; end if;
  execute 'drop trigger if exists pub_harvest on harvests; create trigger pub_harvest after insert on harvests for each row execute function itran_generic_publish(''harvest.done'')';
  execute 'drop trigger if exists pub_po on purchase_orders; create trigger pub_po after insert on purchase_orders for each row execute function itran_generic_publish(''po.created'')';
  execute 'drop trigger if exists pub_order on orders; create trigger pub_order after insert on orders for each row execute function itran_generic_publish(''order.created'')';
  execute 'drop trigger if exists pub_booking on hosp_bookings; create trigger pub_booking after insert on hosp_bookings for each row execute function itran_generic_publish(''booking.created'')';
  execute 'drop trigger if exists pub_event on hosp_events; create trigger pub_event after insert on hosp_events for each row execute function itran_generic_publish(''booking.created'')';
  execute 'drop trigger if exists pub_ship on shipments; create trigger pub_ship after insert or update of status on shipments for each row execute function itran_generic_publish(''shipment.status'')';
  execute 'drop trigger if exists pub_lock on period_locks; create trigger pub_lock after insert on period_locks for each row execute function itran_generic_publish(''period.locked'')';
end $$;
update event_topics set wired=true where topic in ('animal.intake','harvest.done','po.created','order.created','booking.created','shipment.status','period.locked');
-- staff.dept chuẩn hóa về mã phòng ban
update staff set dept = case when role='owner' then 'HDQT' when role='director' and farm_id is null then 'BGD' when role='director' then 'GDT' when role='accountant' then 'TCKT' when role='it_engineer' then 'CNTB' when role='auditor' then 'QA'
  when position ilike 'A1%' or position ilike 'A7%' then 'D5' when position ilike 'A2%' or position ilike 'A3%' or position ilike 'A5%' then 'KTCN' when position ilike 'A4%' then 'SH' when position ilike 'A6%' then 'TT' when position ilike 'A8%' or position ilike 'A10%' then 'CCU' when position ilike 'A9%' then 'KDM' when position ilike 'A11%' then 'CNTB' else coalesce(dept,'KTCN') end
where dept is null or dept not in (select code from departments);
update staff set dept=case dept when 'SHTT' then 'SH' when 'SXCN' then 'D5' else 'KTCN' end where dept not in (select code from departments);
